#include <stdio.h>
int main(void){int n,bt[100],p[100],wt[100],tat[100],i,j,t;float aw=0,at=0;printf("Number of processes: ");scanf("%d",&n);if(n<1||n>100)return 1;for(i=0;i<n;i++){printf("Burst time P%d: ",i+1);scanf("%d",&bt[i]);p[i]=i+1;}for(i=0;i<n;i++)for(j=i+1;j<n;j++)if(bt[j]<bt[i]){t=bt[i];bt[i]=bt[j];bt[j]=t;t=p[i];p[i]=p[j];p[j]=t;}wt[0]=0;for(i=1;i<n;i++)wt[i]=wt[i-1]+bt[i-1];printf("PID\tBT\tWT\tTAT\n");for(i=0;i<n;i++){tat[i]=wt[i]+bt[i];aw+=wt[i];at+=tat[i];printf("P%d\t%d\t%d\t%d\n",p[i],bt[i],wt[i],tat[i]);}printf("Avg WT=%.2f Avg TAT=%.2f\n",aw/n,at/n);}